def hasitem(inv, target):
    s = (inv or '').lower()
    t = target or ''
    return t and t in s and 'not carrying' not in s and 'nothing' not in s

def hook(ctx, nb):
    tt = (ctx.get('task') or {}).get('task_type') or ctx.get('task.task_type') or ''
    target = (ctx.get('task') or {}).get('target_type') or ctx.get('task.target_type') or ''
    dest = (ctx.get('task') or {}).get('destination_type') or ctx.get('task.destination_type') or ''
    verb = needverb(tt)
    if not verb:
        nb['transform_done'] = True
    act = (ctx.get('action') or {}).get('final_action') or ctx.get('action.final_action') or ''
    obs = (ctx.get('observation') or '').lower()
    inv = (ctx.get('world') or {}).get('inventory') or []
    if isinstance(inv, str):
        invs = inv.lower()
    else:
        invs = ' '.join([str(x).lower() for x in inv])
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'put' in obs:
        nb['carrying_target'] = False
    if verb and target and act.startswith(verb + ' ') and target in act and ('you ' + verb in obs or verb + ' the' in obs):
        nb['transform_done'] = True
    pc = (ctx.get('world') or {}).get('placed_count')
    if isinstance(pc, int) and pc > (nb.get('placed_count') or 0):
        nb['placed_count'] = pc
    carrying = hasitem(invs, target)
    wrong = bool(invs and not carrying and 'nothing' not in invs and 'not carrying' not in invs)
    if nb.get('carrying_target') and target and target in invs and not carrying:
        carrying = True
    admiss = ctx.get('admissible') or []
    can_put = False
    for a in admiss:
        s = str(a).lower()
        if target and s.startswith('put ') and target in s and (not dest or dest in s):
            can_put = True
    need = 2 if 'pick_two' in tt else 1
    if wrong:
        nb['stage'] = 'wrong_inventory'
    elif carrying:
        if verb and not nb.get('transform_done'):
            nb['stage'] = 'transform'
        elif can_put:
            nb['stage'] = 'put_target'
        else:
            nb['stage'] = 'go_destination'
    else:
        if need > 1 and (nb.get('placed_count') or 0) >= need:
            nb['stage'] = 'find_target'
        else:
            nb['stage'] = 'take_target' if (ctx.get('world') or {}).get('target_found') else 'find_target'
    nb['wrong_inventory'] = wrong
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['need_verb'] = verb
    return None

