def emit(nb, msg):
    if not msg or nb.get('last_hint') == msg:
        return None
    nb['last_hint'] = msg
    return {'message': msg}

def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('need_verb') or ''
    tt = nb.get('task_type') or ''
    pc = nb.get('placed_count') or 0
    if stage == 'wrong_inventory':
        return emit(nb, 'Inventory appears to hold a non-target item. Do not use it for the goal; recover and search for a ' + target + '.')
    if stage == 'transform' and verb:
        place = 'sinkbasin' if verb == 'clean' else ('microwave' if verb == 'heat' else ('fridge' if verb == 'cool' else 'knife'))
        return emit(nb, 'Before any put action, complete the required ' + verb + ' step with the ' + place + ' while carrying the ' + target + '.')
    if stage == 'put_target' and dest:
        return emit(nb, 'The ' + target + ' is ready; use the admissible put action at the ' + dest + ' and do not take it back.')
    need = 2 if 'pick_two' in tt else 1
    if stage == 'take_target' and need > 1 and pc > 0 and pc < need:
        return emit(nb, 'Leave already placed ' + target + ' objects where they are; find and take another ' + target + ' for the ' + dest + '.')
    return None

