def hook(ctx, nb):
    tt = nb.get('task_type') or (ctx.get('task') or {}).get('task_type') or ''
    target = nb.get('target_type') or (ctx.get('task') or {}).get('target_type') or ''
    dest = nb.get('destination_type') or (ctx.get('task') or {}).get('destination_type') or ''
    verb = needverb(tt)
    if not verb:
        return None
    act = (ctx.get('action') or {}).get('final_action') or ctx.get('action.final_action') or ''
    inv = (ctx.get('world') or {}).get('inventory') or []
    if isinstance(inv, str):
        invs = inv.lower()
    else:
        invs = ' '.join([str(x).lower() for x in inv])
    carrying = hasitem(invs, target) or (nb.get('carrying_target') and target and target in invs)
    if not carrying:
        return None
    if act.startswith('put ') and target and target in act and not nb.get('transform_done'):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the ' + target + ' yet. First complete the required ' + verb + ' step, then put it at the ' + dest + '.'}
    if act.startswith('put ') and target and target in act and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'That is not the requested destination. Carry the ' + target + ' to the ' + dest + ' and put it there.'}
    if act.startswith('examine ') and target and target in act and not nb.get('transform_done') and 'transform' in act:
        return {'kind': 'block_and_prompt', 'message': 'This task does not require examining the target. Use the ' + verb + ' action with the proper tool/appliance first.'}
    return None
